  return <form onSubmit={submit} className={styles.assetFormPage}><button type="button" onClick={()=>onPage("Asset Register")}>← Back to Asset Register</button><APanel title="Asset Identity" subtitle="Core identification and classification"><div className={styles.assetFormGrid}><Field name="name" label="Asset Name *" required/><Field name="tag" label="Asset Tag" placeholder="Generated automatically" disabled/><Select name="category" label="Category *" options={categories.map(x=>x.name)} required/><Field name="brand" label="Brand"/><Field name="model" label="Model Number"/><Field name="serial" label="Serial Number"/><Field name="quantity" label="Quantity *" type="number" defaultValue="1" required/><label className={styles.assetWide}>Description<textarea name="notes"/></label></div></APanel><APanel title="Status & Location" subtitle="Availability, condition and acquisition"><div className={styles.assetFormGrid}><Select name="status" label="Status" options={["In Store","In Use","Under Maintenance","Retired","Lost"]}/><Select name="condition" label="Condition" options={["New","Good","Fair","Poor","Damaged"]}/><Field name="location" label="Physical Location *" required/><Field name="supplier" label="Supplier"/><Select name="funding" label="Funding Source" options={["School Fund","Gov Grant","Donation","CSR","Other"]}/><Field name="purchaseDate" label="Purchase Date" type="date"/><Field name="purchaseCost" label="Purchase Cost (₹)" type="number"/><Field name="invoice" label="Invoice Number"/></div></APanel><APanel title="Depreciation" subtitle="Book value calculation"><div className={styles.assetFormGrid}><Select name="method" label="Method" options={["No Depreciation","Straight Line","Written Down Value","Declining Balance"]}/><Field name="depreciationStart" label="Start Date" type="date"/><Field name="life" label="Useful Life (months)" type="number" defaultValue="60"/><Field name="salvage" label="Salvage Value (₹)" type="number" defaultValue="0"/><Field name="rate" label="Rate (% / year)" type="number" defaultValue="20"/><Field name="openingValue" label="Opening Book Value (₹)" type="number"/></div></APanel><APanel title="Warranty, Insurance & Media"><div className={styles.assetFormGrid}><Field name="warrantyProvider" label="Warranty Provider"/><Field name="warrantyExpiry" label="Warranty Expiry" type="date"/><label className={styles.assetCheck}><input name="insured" type="checkbox"/><span>Asset is insured</span></label><Field name="insuranceProvider" label="Insurance Provider"/><Field name="policy" label="Policy Number"/><Field name="insuranceExpiry" label="Insurance Expiry" type="date"/><Field name="photo" label="Asset Photo" type="file"/><Field name="warrantyDoc" label="Warranty Document" type="file"/><Field name="purchaseDoc" label="Purchase Document" type="file"/></div></APanel><div className={styles.assetFormActions}><button type="button" onClick={()=>onPage("Asset Register")}>Cancel</button><button>Register Asset</button></div></form>;
