function Field({label,name,type="text",defaultValue,placeholder,required,disabled}:{label:string;name:string;type?:string;defaultValue?:string;placeholder?:string;required?:boolean;disabled?:boolean}){return <label>{label}<input name={name} type={type} defaultValue={defaultValue} placeholder={placeholder} required={required} disabled={disabled}/></label>;}
function Select({label,name,options,required}:{label:string;name:string;options:string[];required?:boolean}){return <label>{label}<select name={name} required={required}>{options.map(x=><option key={x}>{x}</option>)}</select></label>;}

function AssetDetails({asset,onPage}:{asset:Asset;onPage:(p:string)=>void}){return <><button className={styles.assetBack} onClick={()=>onPage("Asset Register")}>← Back to Asset Register</button><section className={styles.assetDetailHero}><i>{asset.category.slice(0,2).toUpperCase()}</i><div><code>{asset.tag}</code><h2>{asset.name}</h2><p>{asset.brand} {asset.model} · Serial {asset.serial}</p></div><Badge value={asset.status}/><button onClick={()=>globalThis.print()}>Print Tag</button></section><section className={styles.assetDetailGrid}><APanel title="Asset Information"><dl>{[["Category",asset.category],["Quantity",String(asset.quantity)],["Condition",asset.condition],["Location",asset.location],["Supplier",asset.supplier],["Funding Source",asset.funding],["Purchase Date",asset.purchaseDate],["Invoice",asset.invoice]].map(([a,b])=><div key={a}><dt>{a}</dt><dd>{b||"—"}</dd></div>)}</dl></APanel><APanel title="Financial Value"><dl>{[["Purchase Cost",money(asset.purchaseCost)],["Book Value",money(bookValue(asset))],["Method",asset.method],["Rate",`${asset.rate}% per year`],["Useful Life",`${asset.life} months`],["Salvage Value",money(asset.salvage)]].map(([a,b])=><div key={a}><dt>{a}</dt><dd>{b}</dd></div>)}</dl></APanel><APanel title="Warranty & Insurance"><dl>{[["Warranty Provider",asset.warrantyProvider],["Warranty Expiry",asset.warrantyExpiry],["Insured",asset.insured?"Yes":"No"],["Insurance Provider",asset.insuranceProvider],["Policy Number",asset.policy],["Insurance Expiry",asset.insuranceExpiry]].map(([a,b])=><div key={a}><dt>{a}</dt><dd>{b||"—"}</dd></div>)}</dl></APanel><APanel title="Movement Timeline"><div className={styles.assetTimeline}>{["Asset registered","Purchase information verified",asset.status==="In Use"?"Allocated to custodian":"Moved to current location"].map((x,i)=><p key={x}><i>✓</i><span><b>{x}</b><small>{i?asset.purchaseDate:asset.depreciationStart}</small></span></p>)}</div></APanel></section></>;}
function AssetTags({assets}:{assets:Asset[]}){return <><div className={styles.assetPrintBar}><div><h2>Print Asset Tags</h2><p>Select records, then print QR-ready labels.</p></div><button onClick={()=>globalThis.print()}>▦ Print Selected</button></div><section className={styles.assetTags}>{assets.slice(0,12).map(x=><label key={x.id}><input type="checkbox" defaultChecked/><article><i>▦</i><div><b>{x.tag}</b><span>{x.name}</span><small>Hig School · {x.location}</small></div></article></label>)}</section></>;}

